import { useState, useEffect, useMemo } from 'react';
import { Link } from 'react-router-dom';
import Layout, { StatCard } from '../components/Layout';
import './DashboardCandidat.css';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';
const DAY_MS = 24 * 60 * 60 * 1000;

const TABS = [
  { key: 'all', label: 'Toutes les offres' },
  { key: 'new', label: 'Nouvelles' },
  // 'saved' nécessite l'endpoint de sauvegarde côté backend (pas encore implémenté)
];

const AVATAR_COLORS = ['#185fa5', '#2a9d8f', '#8e6bb0', '#c9822a', '#4a6fa5'];
function getAvatarColor(name = '') {
  const sum = [...name].reduce((acc, c) => acc + c.charCodeAt(0), 0);
  return AVATAR_COLORS[sum % AVATAR_COLORS.length];
}

export default function DashboardCandidat() {
  const [jobs, setJobs] = useState([]);
  const [status, setStatus] = useState('loading');
  const [search, setSearch] = useState('');
  const [activeTab, setActiveTab] = useState('all');

  useEffect(() => {
    const controller = new AbortController();

    fetch(`${API_URL}/api/jobs`, { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`Erreur serveur (${res.status})`);
        return res.json();
      })
      .then((data) => {
        setJobs(data);
        setStatus('success');
      })
      .catch((err) => {
        if (err.name !== 'AbortError') {
          console.error('Erreur chargement offres:', err);
          setStatus('error');
        }
      });

    return () => controller.abort();
  }, []);

  const jobsWithFreshness = useMemo(
    () =>
      jobs.map((job) => ({
        ...job,
        isNew: Date.now() - new Date(job.createdAt).getTime() < DAY_MS,
      })),
    [jobs]
  );

  const stats = useMemo(() => {
    const newCount = jobsWithFreshness.filter((j) => j.isNew).length;
    return { total: jobs.length, new: newCount };
  }, [jobs, jobsWithFreshness]);

  const visibleJobs = useMemo(() => {
    let list = jobsWithFreshness;
    if (activeTab === 'new') list = list.filter((j) => j.isNew);
    const q = search.trim().toLowerCase();
    if (q) {
      list = list.filter(
        (j) => j.title.toLowerCase().includes(q) || j.company?.toLowerCase().includes(q)
      );
    }
    return list;
  }, [jobsWithFreshness, activeTab, search]);

  return (
    <Layout
      role="candidat"
      activeKey="jobs"
      userName="Vous"
      userRole="Candidat"
      searchValue={search}
      onSearchChange={setSearch}
      searchPlaceholder="Rechercher un poste, une entreprise..."
    >
      <div className="page-header">
        <div>
          <h1 className="page-title">Offres d'emploi</h1>
          <p className="page-subtitle">Parcourez les offres disponibles et postulez en un clic</p>
        </div>
      </div>

      <div className="stats-row">
        <StatCard value={stats.total} label="Offres disponibles" accent="#185fa5" />
        <StatCard value={stats.new} label="Nouvelles cette semaine" accent="#2ea86a" />
        {/* Ces deux stats nécessitent le suivi des candidatures / offres sauvegardées côté backend */}
        <StatCard value={0} label="Candidatures envoyées" accent="#e0a13a" />
        <StatCard value={0} label="Offres sauvegardées" accent="#8e6bb0" />
      </div>

      <div className="tabs-row">
        {TABS.map((tab) => (
          <button
            key={tab.key}
            className={`tab-btn${activeTab === tab.key ? ' tab-btn-active' : ''}`}
            onClick={() => setActiveTab(tab.key)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div className="list-meta">
        <span>{visibleJobs.length} offre{visibleJobs.length > 1 ? 's' : ''}</span>
      </div>

      {status === 'loading' && (
        <div className="jobs-grid" aria-busy="true">
          {Array.from({ length: 3 }).map((_, i) => (
            <div key={i} className="job-card job-card-skeleton" />
          ))}
        </div>
      )}

      {status === 'error' && (
        <div className="state-panel state-error">Impossible de charger les offres pour le moment.</div>
      )}

      {status === 'success' && visibleJobs.length === 0 && (
        <div className="state-panel">Aucune offre ne correspond à votre recherche.</div>
      )}

      {status === 'success' && visibleJobs.length > 0 && (
        <div className="jobs-grid">
          {visibleJobs.map((job) => (
            <div key={job.id} className="job-card">
              <div className="job-card-top">
                <div
                  className="job-card-avatar"
                  style={{ backgroundColor: getAvatarColor(job.company) }}
                  aria-hidden="true"
                >
                  {job.company?.charAt(0)?.toUpperCase() || '?'}
                </div>
                {job.isNew && <span className="job-card-badge">Nouveau</span>}
              </div>

              <h3 className="job-card-title">{job.title}</h3>
              <p className="job-card-company">{job.company}</p>

              <div className="job-card-tags">
                {job.type && <span className="tag">{job.type}</span>}
                {job.contract && <span className="tag">{job.contract}</span>}
                {job.location && <span className="tag">{job.location}</span>}
              </div>

              <div className="job-card-actions">
                {/* Postuler : backend pas encore branché, voir note de suivi */}
                <button type="button" className="btn-apply">Postuler</button>
                <Link to={`/job/${job.id}`} className="job-card-link">Voir le détail</Link>
              </div>
            </div>
          ))}
        </div>
      )}
    </Layout>
  );
}
